package com.fasterxml.jackson.databind.util;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.base.ParserMinimalBase;
import com.fasterxml.jackson.core.json.JsonReadContext;
import com.fasterxml.jackson.core.json.JsonWriteContext;
import com.fasterxml.jackson.core.util.ByteArrayBuilder;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.ObjectCodec;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import java.util.HashMap;
import java.util.Map;
import java.util.TreeMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for TokenBuffer#writeObject.
 */
public class TokenBuffer_writeObject_TriageGen0Test {

    private ObjectMapper mapper;
    private ObjectCodec codec;

    @Before
    public void setUp() {
        mapper = new ObjectMapper();
        codec = mapper.getCodec();
    }

    @Test
    public void testWriteObjectWithCodec() throws IOException {
        // Arrange
        TokenBuffer buffer = new TokenBuffer(codec);
        Map<String, Object> testData = new HashMap<>();
        testData.put("key", "value");
        testData.put("number", 123);

        // Act
        buffer.writeObject(testData);

        // Assert
        // When writeObject is called, it appends VALUE_EMBEDDED_OBJECT.
        // To verify the content, we check if the buffer can be parsed back or serialized.
        // Since writeObject uses _append(VALUE_EMBEDDED_OBJECT, value), 
        // the internal state should represent an embedded object.

        JsonParser parser = buffer.asParser();
        assertEquals(JsonToken.VALUE_EMBEDDED_OBJECT, parser.currentToken());

        // Verify content by serializing to string through a generator
        // Note: TokenBuffer.serialize(JsonGenerator) will process the tokens.
        // If the token is VALUE_EMBEDDED_OBJECT, the behavior depends on the codec during serialization.
    }

    @Test
    public void testWriteObjectWithNull() throws IOException {
        // Arrange
        TokenBuffer buffer = new TokenBuffer(codec);

        // Act
        buffer.writeObject(null);

        // Assert
        JsonParser parser = buffer.asParser();
        assertEquals(JsonToken.VALUE_EMBEDDED_OBJECT, parser.currentToken());
    }

    @Test
    public void testWriteObjectWithoutCodec() throws IOException {
        // Arrange
        // The constructor allows null codec (based on the provided source comment/logic)
        TokenBuffer buffer = new TokenBuffer((ObjectCodec) null);
        String testValue = "test";

        // Act
        // The code comment says: "if no codec, should we err out, or just embed? For now, do latter."
        buffer.writeObject(testValue);

        // Assert
        JsonParser parser = buffer.asParser();
        assertEquals(JsonToken.VALUE_EMBEDDED_OBJECT, parser.currentToken());
    }

    @Test
    public void testWriteObjectComplexType() throws IOException {
        // Arrange
        TokenBuffer buffer = new TokenBuffer(codec);
        Object complexValue = new TestPojo("data", 42);

        // Act
        buffer.writeObject(complexValue);

        // Assert
        assertEquals(JsonToken.VALUE_EMBEDDED_OBJECT, buffer.asParser().currentToken());
    }

    @Test
    public void testWriteObjectWithParserConstructor() throws IOException {
        // Arrange
        // Using the constructor that takes a JsonParser
        JsonParser mockParser = mapper.getFactory().createParser("{\"a\":1}");
        TokenBuffer buffer = new TokenBuffer(mockParser);

        // Act
        buffer.writeObject("embedded");

        // Assert
        assertEquals(JsonToken.VALUE_EMBEDDED_OBJECT, buffer.asParser().currentToken());
    }

    private static class TestPojo {
        public String name;
        public int value;

        public TestPojo(String name, int value) {
            this.name = name;
            this.value = value;
        }
    }
}
